export type Pairing = {id:string; a:string; b:string; type:'bridge'|'contrast'; novelty:1|2|3; connection:string; why:string; dish:string; method:string};
const rows: [string,string,1|2|3,string,string,string][] = [
 ['strawberry','basil',1,'A floral thread runs through both ingredients. Basil’s green freshness lifts the fruit without covering it.','Strawberry, basil & olive oil','Slice ripe strawberries, add torn basil and a few drops of mild olive oil. Finish with flaky salt just before serving.'],
 ['strawberry','tomato',2,'Sweet, caramel-like and green aroma notes connect these two fruits. Tomato moves strawberry into savoury territory.','Strawberry & tomato gazpacho','Blend two parts ripe tomato with one part strawberry, a splash of sherry vinegar and salt. Chill, then finish with olive oil.'],
 ['strawberry','pepper',2,'Juicy sweetness meets the citrus, wood and gentle heat of freshly cracked pepper. The interest lies in the contrast.','Peppered strawberries on toast','Macerate sliced strawberries with a little sugar for 10 minutes. Spoon onto toasted sourdough and finish with one light turn of black pepper.'],
 ['strawberry','chocolate',1,'Roasted bitterness gives the bright fruit a deeper backdrop. Balance matters more here than a count of shared molecules.','Strawberry & dark chocolate crémeux','Serve a small portion of dark chocolate crémeux with fresh strawberries. Keep the fruit unsweetened to hold onto its acidity.'],
 ['strawberry','olive',2,'Green, grassy notes can connect the fruit and a fresh olive oil. The oil also adds a silky texture that carries aroma.','Strawberry carpaccio, green olive oil','Slice strawberries thinly. Dress with a mild extra virgin olive oil, a few drops of lemon and flaky salt. Serve immediately.'],
 ['strawberry','mushroom',3,'An exploratory meeting of juicy fruit and earthy mushroom. This is a kitchen hypothesis: use roasted shiitake sparingly.','Roasted shiitake with strawberry relish','Roast sliced shiitake until crisp at the edges. Add a small spoon of finely diced strawberry with vinegar and salt. Taste the components together before plating.'],
 ['strawberry','lemon',1,'A floral aroma connection supports a familiar bright combination. Lemon juice adjusts acidity; its zest adds a different aromatic layer.','Fresh strawberry & lemon granita','Macerate strawberries, blend with a little water and sugar, and adjust with lemon juice. Freeze and scrape; add fresh zest to serve.'],
 ['strawberry','parmesan',3,'Sweet acidity meets salt, umami and a nutty finish. Shave the cheese finely so it acts as a seasoning for the fruit.','Strawberry, Parmesan & black pepper','Plate sliced ripe strawberries with a few fine shavings of aged Parmesan. Finish with black pepper and a very small drizzle of olive oil.'],
 ['basil','tomato',1,'Herbal freshness plays against the tomato’s sweet acidity and savoury character. Keep the basil fresh and the tomato at room temperature.','Tomato salad with torn basil','Cut ripe tomatoes, season with salt and rest for 10 minutes. Add torn basil and olive oil just before serving.'],
 ['basil','pepper',2,'Fresh herbal aroma meets woody spice. Use pepper lightly to give the basil definition without overwhelming its floral notes.','Basil & black pepper dressing','Finely chop basil and whisk with olive oil, lemon juice and freshly cracked pepper. Spoon over steamed vegetables.'],
 ['basil','chocolate',3,'Basil’s aromatic freshness cuts through cocoa’s roasted depth. An exploratory combination that works best with a light infusion.','Basil-infused chocolate ganache','Infuse warm cream or oat cream with basil for 10 minutes, strain and use to make a dark chocolate ganache. Taste a small batch first.'],
 ['basil','olive',1,'Green leaf aromas meet a grassy oil. The oil carries the delicate basil notes; blending gently keeps the result fresh.','Fresh basil oil','Briefly blanch basil, cool and dry well. Blend with a mild olive oil and use immediately over vegetables or soup.'],
 ['basil','mushroom',2,'Earthy depth provides a base for basil’s fresh herbal aroma. Add the leaves after cooking so the contrast stays clear.','Seared shiitake with basil','Sear shiitake in a hot pan until golden. Season, remove from the heat, then fold through torn basil.'],
 ['basil','lemon',1,'A shared floral note links basil with lemon zest. Citrus acidity can make the herbal aroma feel especially fresh.','Basil & lemon sorbet','Make a light sugar syrup, cool and briefly infuse with basil. Add lemon juice to taste, strain and churn.'],
 ['basil','parmesan',1,'Nutty, savoury cheese gives fresh basil a rounded foundation. This familiar contrast is the backbone of pesto.','Basil & Parmesan pesto','Crush basil with a small amount of garlic and pine nuts. Fold in finely grated Parmesan and olive oil; adjust with lemon.'],
 ['tomato','pepper',1,'Aromatic pepper adds woody warmth to the tomato’s green, fruity character. Fresh grinding keeps the citrus notes alive.','Slow tomatoes, cracked pepper','Slow-roast tomato halves with olive oil and salt. Finish with fresh pepper after roasting.'],
 ['tomato','chocolate',3,'Cocoa’s bitterness can deepen cooked tomato. This is an exploratory savoury pairing: a little chocolate goes a long way.','Tomato & cocoa braise','Cook down a tomato sauce with onion and smoked chilli. Stir in a small shaving of dark chocolate and taste before adding more.'],
 ['tomato','olive',1,'A shared green aroma provides a natural bridge. The oil softens the perception of acidity and carries the tomato’s aroma.','Tomato water & olive oil','Salt chopped tomatoes and drain through a fine cloth. Serve the clear tomato water cold with a few droplets of fragrant olive oil.'],
 ['tomato','mushroom',1,'Both contribute savoury character, while tomato’s acidity balances the earthy richness of mushrooms.','Roasted tomato & shiitake broth','Roast tomatoes and shiitake, then simmer gently with water. Strain, season and serve with a few fresh tomato pieces.'],
 ['tomato','lemon',2,'Citrus brightness sharpens the tomato’s fruity side. Use zest when the tomato already has enough acidity.','Tomato confit with lemon zest','Slowly cook tomato halves in olive oil. Add a little fresh lemon zest after cooking and serve on toast.'],
 ['tomato','parmesan',1,'Tomato acidity and savoury cheese balance each other. The cheese adds salt and a long, nutty finish.','Tomato risotto, Parmesan crisp','Fold roasted tomatoes into a simple risotto. Finish with Parmesan and serve with a thin baked cheese crisp.'],
 ['pepper','chocolate',2,'Wood and spice bring a new dimension to roasted cocoa. Grind pepper finely and add gradually to avoid a harsh finish.','Black pepper chocolate truffles','Add a small pinch of finely ground pepper to dark chocolate ganache. Chill, shape and coat in cocoa.'],
 ['pepper','olive',1,'The woody aroma of pepper reinforces the peppery finish of some olive oils. Choose a mild oil to keep the balance gentle.','Pepper & olive oil flatbread','Brush warm flatbread with olive oil and finish with freshly cracked pepper and a little flaky salt.'],
 ['pepper','mushroom',1,'Woody spice complements earthy mushroom aroma, while pepper’s heat keeps a rich preparation lively.','Pepper-crusted shiitake','Sear thick slices of shiitake, then finish with cracked pepper and a splash of stock. Reduce briefly and serve.'],
 ['pepper','lemon',1,'Limonene provides a citrus bridge between pepper and lemon zest. Their fresh aromatic notes work alongside pepper’s warmth.','Lemon-pepper finishing salt','Rub finely grated lemon zest into flaky salt. Mix in fresh cracked pepper and use immediately on roast vegetables.'],
 ['pepper','parmesan',1,'A classic balance of spice, salt and nutty richness. Toasting the pepper briefly brings its aroma forward.','Cacio e pepe','Toast cracked pepper gently, add starchy pasta water and toss with pasta. Off the heat, work in finely grated cheese to make a smooth sauce.'],
 ['chocolate','olive',2,'A fruity oil adds texture and fresh green aroma to rich cocoa. Choose an oil with a gentle finish.','Chocolate mousse & olive oil','Serve a small chocolate mousse with a teaspoon of fruity olive oil and a few flakes of salt.'],
 ['chocolate','mushroom',3,'Earthy mushroom and roasted cocoa make an unusual savoury experiment. Keep the cocoa unsweetened and use only a little.','Shiitake with a cocoa jus','Roast shiitake and reduce the pan juices with vegetable stock. Whisk in a pinch of unsweetened cocoa; taste before increasing.'],
 ['chocolate','lemon',2,'A bright citrus accent cuts through cocoa’s richness. Zest gives aroma with less disruption to texture than juice.','Dark chocolate, lemon zest & salt','Spread thin melted chocolate on parchment, add finely grated lemon zest and salt, then chill and break into pieces.'],
 ['chocolate','parmesan',3,'Roasted bitterness meets nutty, salty cheese. An exploratory pairing for tiny portions and careful tasting.','Dark chocolate & Parmesan tasting bite','Serve a small shard of dark chocolate with a paper-thin shaving of Parmesan. Adjust their proportions before building a dish around them.'],
 ['olive','mushroom',1,'Green oil freshens earthy mushrooms while adding texture. Save a little oil to add after cooking.','Warm shiitake, fresh olive oil','Pan-roast shiitake, season with salt and finish off the heat with a drizzle of fresh extra virgin olive oil.'],
 ['olive','lemon',1,'Citrus aroma and acidity brighten the oil’s grassy character. The balance can move from sharp dressing to gentle finishing oil.','Lemon & olive oil dressing','Whisk one part lemon juice with three parts olive oil. Season, then add a little zest if more citrus aroma is needed.'],
 ['olive','parmesan',1,'Grassy aroma, nutty cheese and rounded fat give a simple combination considerable depth.','Parmesan & olive oil toast','Toast sourdough, brush with fragrant olive oil and cover with finely grated Parmesan while still warm.'],
 ['mushroom','lemon',2,'Fresh citrus lifts earthy mushroom aroma. Add it at the end so its brightness remains distinct.','Charred shiitake with lemon','Sear shiitake over high heat. Take off the heat, add a small squeeze of lemon and finish with zest.'],
 ['mushroom','parmesan',1,'Two savoury ingredients build depth together. Parmesan also adds salt and a nutty finish to earthy shiitake.','Shiitake & Parmesan risotto','Fold browned shiitake into risotto. Take off the heat and finish with finely grated Parmesan.'],
 ['lemon','parmesan',1,'Lemon’s brightness keeps aged cheese from feeling heavy. Use zest for aroma and juice only as needed for balance.','Lemon & Parmesan pasta','Toss warm pasta with grated Parmesan, starchy water and lemon zest. Add lemon juice a little at a time, tasting as you go.'],
["raspberry", "basil", 2, "Fresh basil gives the tart berry a green, floral lift. Keep the leaves raw and use them as an accent.", "Raspberry & basil granita", "Blend raspberries with a little sugar syrup and lemon, freeze and scrape. Finish with finely torn basil."],
["raspberry", "beetroot", 2, "Berry acidity interrupts beetroot’s earthy sweetness. The colour connection is useful, but the interest is in the contrast.", "Roast beetroot, raspberry vinaigrette", "Roast beetroot until tender. Dress warm wedges with crushed raspberries, vinegar and olive oil."],
["raspberry", "chocolate", 1, "Tart red fruit cuts through cocoa’s roasted richness. Keep the chocolate portion small enough to let the berry lead.", "Dark chocolate & fresh raspberry", "Serve a thin slice of chocolate tart with unsweetened crushed raspberries and a pinch of salt."],
["raspberry", "rosemary", 3, "A restrained piney infusion gives the berry an unexpected savoury edge. Too much rosemary quickly overwhelms its perfume.", "Raspberry sorbet, rosemary syrup", "Briefly infuse a small rosemary sprig in warm syrup and remove it. Cool, blend with raspberry purée and churn."],
["raspberry", "goat-cheese", 2, "Fresh cheese gives tang and creaminess while the berry provides juicy acid. A crisp element makes the contrast clearer.", "Raspberry, chèvre & rye crisp", "Spread fresh goat cheese on a rye crisp. Add a raspberry half and a little black pepper just before serving."],
["blueberry", "lemon", 1, "Lemon zest lifts the blueberry’s quiet floral character. Juice is useful only if the fruit needs more acidity.", "Blueberry & lemon compote", "Warm half the berries with a little sugar until they burst. Fold in the remaining berries and finish with lemon zest."],
["blueberry", "cardamom", 2, "Cool, fragrant spice adds definition to mild berries. Infuse the pods lightly so the fruit remains recognisable.", "Blueberry & cardamom custard", "Bruise one cardamom pod into warm custard, then strain. Serve with briefly warmed blueberries."],
["blueberry", "miso", 3, "A little fermented salt creates a savoury counterpoint to the berries. Treat miso as seasoning, not a second sauce.", "Blueberry with white miso cream", "Whisk a small amount of white miso into unsweetened cream or oat cream. Serve a teaspoon beside fresh blueberries."],
["blueberry", "thyme", 2, "A gentle herbal note makes the fruit feel less obviously sweet. Fresh leaves give a cleaner result than a long infusion.", "Warm blueberries & thyme", "Warm blueberries in a pan with a splash of water. Finish with a few picked thyme leaves and a little lemon."],
["blueberry", "hazelnut", 1, "Roasted crunch gives soft berries structure. Use unsweetened nuts if the berries are already very ripe.", "Blueberries, hazelnut & yoghurt", "Spoon blueberries over thick yoghurt, then finish with freshly toasted, chopped hazelnuts."],
["blackberry", "duck", 1, "Tart, dark fruit balances the richness of duck and its rendered skin. Keep the sauce sharp rather than jammy.", "Duck with blackberry pan sauce", "Cook the duck breast and rest it. Deglaze the pan, add crushed blackberries and a little vinegar, then strain if desired."],
["blackberry", "blue-cheese", 2, "Berry acidity and fine tannins cut into salty, creamy cheese. Use a small cheese portion so it does not dominate.", "Blackberry & blue cheese toast", "Spread a little blue cheese on warm toast, add halved blackberries and finish with black pepper."],
["blackberry", "thyme", 2, "Warm herbal aroma gives the dark fruit a savoury direction. A few leaves are enough to change the impression.", "Blackberry & thyme reduction", "Reduce a little blackberry juice with stock or water. Add thyme briefly, remove the sprig and balance with vinegar."],
["blackberry", "coffee", 3, "Roasted bitterness can frame dark fruit in an unusual way. Use a light coffee infusion to avoid a muddy finish.", "Blackberry, coffee cream & cocoa", "Lightly infuse cream with coffee, strain and cool. Serve a small spoon with fresh blackberries and a little cocoa."],
["blackberry", "vanilla", 1, "Vanilla softens the perception of the berry’s tartness without needing much extra sugar.", "Blackberry & vanilla fool", "Fold a lightly sweetened blackberry purée through vanilla cream, leaving visible streaks and some fresh fruit."],
["cherry", "duck", 1, "Bright fruit balances rich duck, while a savoury pan sauce keeps the combination from becoming dessert-like.", "Duck with fresh cherry jus", "Cook and rest duck breast. Reduce its pan juices with stock, add pitted cherries at the end and balance with a little vinegar."],
["cherry", "pepper", 2, "Fresh pepper adds woody warmth and a hint of citrus to juicy cherries. Grind it at the last moment.", "Warm cherries, black pepper & cream", "Warm pitted cherries just enough to release some juice. Serve with unsweetened cream and a very light grind of pepper."],
["cherry", "chocolate", 1, "Dark cocoa gives the fruit depth, while cherry acidity cuts through richness. Choose a chocolate with restrained sweetness.", "Cherry & dark chocolate ganache", "Serve a small chocolate ganache with fresh pitted cherries and a spoon of their unsweetened juice."],
["cherry", "thyme", 2, "A warm herbal accent makes ripe cherry useful in savoury cooking. Keep the thyme delicate and the fruit bright.", "Cherry & thyme relish", "Finely chop pitted cherries with a little vinegar and salt. Stir in a few picked thyme leaves just before serving."],
["cherry", "goat-cheese", 2, "Tangy cheese and juicy fruit share the plate without needing a sugary bridge. Crisp bread keeps the textures distinct.", "Cherry, chèvre & sourdough", "Toast thin sourdough, spread with fresh chèvre and top with pitted cherry halves."],
["peach", "basil", 1, "Floral fruit and fresh herb have a natural aromatic affinity. The basil should lift, not cover, the peach.", "Peach & basil salad", "Slice ripe peaches, season lightly with salt and add torn basil. Finish with olive oil and a little lemon if needed."],
["peach", "tomato", 2, "Two juicy fruits meet across the sweet–savoury boundary. Tomato acidity gives a ripe peach more definition.", "Peach & tomato crudo", "Slice peaches and ripe tomatoes. Salt gently, rest briefly and dress with olive oil and a few drops of vinegar."],
["peach", "rosemary", 2, "Resinous rosemary gives soft fruit a darker aromatic edge. Infuse the herb briefly rather than chopping in a large amount.", "Grilled peach, rosemary oil", "Warm olive oil with a small rosemary sprig, then remove it. Brush onto briefly grilled peach halves."],
["peach", "miso", 3, "Fermented salt brings out the savoury potential of caramelised peach. Use white miso sparingly in the glaze.", "Miso-glazed grilled peach", "Thin white miso with water and a little honey or sugar. Brush a small amount onto peach halves after grilling."],
["peach", "vanilla", 1, "Vanilla rounds the peach’s creamy fruit notes. Keep the added sweetness low when the peaches are fully ripe.", "Roast peach with vanilla cream", "Roast peach halves until just tender. Serve with lightly infused vanilla cream and their cooking juices."],
["apricot", "rosemary", 2, "The apricot’s sweet acidity holds up to a piney accent. A short infusion keeps the pairing fragrant rather than medicinal.", "Roast apricot & rosemary", "Roast apricot halves with a little oil and a small rosemary sprig. Remove the herb before serving."],
["apricot", "goat-cheese", 1, "Tangy cheese and soft, acidic fruit balance each other. The combination can work as a savoury starter or a restrained dessert.", "Apricot, chèvre & toast", "Briefly roast apricot halves. Serve warm over fresh goat cheese on crisp toast."],
["apricot", "cardamom", 2, "Fragrant cardamom lifts the fruit’s perfume while its acidity keeps the result lively. Start with one lightly bruised pod.", "Apricot & cardamom compote", "Poach apricot pieces gently with a bruised cardamom pod and a little syrup. Remove the pod before serving."],
["apricot", "pork", 1, "Apricot acidity and sweetness offset pork’s mild richness. A touch of vinegar prevents the sauce from becoming jam-like.", "Pork with apricot pan sauce", "Cook the pork through and rest it. Deglaze the pan, add chopped apricots and finish with a little cider vinegar."],
["pear", "blue-cheese", 1, "Juicy, gentle sweetness makes a useful foil for pungent, salty cheese. A crisp pear gives the cleanest contrast.", "Pear & blue cheese salad", "Slice a firm pear thinly and scatter with a small amount of blue cheese. Add leaves and a light vinaigrette."],
["pear", "cardamom", 2, "Cool aromatic spice adds lift to the pear’s subtle perfume. Keep the poaching liquid light and the pear identifiable.", "Cardamom-poached pear", "Poach peeled pear wedges with one bruised cardamom pod in lightly sweetened water. Remove the pod and serve with the reduced liquid."],
["pear", "hazelnut", 1, "Roasted nuts give a soft, mild fruit both aroma and crunch. A warm pear makes the hazelnut fragrance more noticeable.", "Warm pear & hazelnut crumble", "Roast pear wedges until tender and finish with chopped toasted hazelnuts and a few crisp oat crumbs."],
["pear", "celery", 3, "Crisp fruit and crisp vegetable offer different kinds of freshness. Pear sweetness softens celery’s herbal bitterness.", "Pear & celery salad", "Slice a firm pear and celery very thinly. Dress with lemon, olive oil and a small pinch of salt."],
["pear", "coffee", 3, "A light roasted accent can give the pear an unexpectedly deep finish. Keep the coffee more like a seasoning than a soak.", "Poached pear with coffee syrup", "Poach a pear in light syrup. Add a little brewed coffee to a spoon of the syrup and serve it separately for careful dosing."],
["apple", "pork", 1, "Crisp acidity is a direct counterpoint to pork’s richness. A raw or lightly cooked apple keeps the plate from feeling heavy.", "Pork, apple & cider pan sauce", "Cook pork through and rest. Deglaze with cider, reduce and add thin apple slices just long enough to soften their edges."],
["apple", "celery", 1, "The two ingredients share a crisp, green impression, but apple brings sweetness to celery’s herbal bite.", "Apple & celery remoulade", "Cut apple and celery into fine matchsticks. Dress lightly with yoghurt, mustard and lemon."],
["apple", "fennel", 2, "Anise-scented fennel adds aromatic depth to crisp orchard fruit. Slice both thinly so neither dominates the texture.", "Apple & shaved fennel", "Shave fennel and a tart apple. Dress with lemon and olive oil, then finish with a few fennel fronds."],
["apple", "miso", 3, "Fermented salt turns caramelised apple toward savoury cooking. White miso works best as a small finishing addition.", "Roast apple with miso butter", "Roast apple wedges until lightly browned. Brush with a little butter mixed with white miso and return briefly to the oven."],
["apple", "thyme", 1, "Warm herbal notes give cooked apple a savoury direction. Use a small sprig during cooking and remove it.", "Apple & thyme pan roast", "Sauté apple wedges in butter with a small thyme sprig until golden. Season lightly and serve warm."],
["orange", "fennel", 1, "Citrus freshness and anise aroma are a clear, lively combination. Orange juice also softens raw fennel’s intensity.", "Orange & fennel salad", "Combine orange segments with finely shaved fennel. Dress with olive oil and a spoon of orange juice."],
["orange", "duck", 1, "Citrus acid and a little bitterness balance the fat and savoury depth of duck. Keep the sauce bright, not syrupy.", "Duck with orange jus", "Cook and rest duck. Reduce the pan juices with stock and orange juice, then finish with a little fresh zest."],
["orange", "coffee", 2, "Roasted bitterness gives sweet citrus a deeper backdrop. Use zest or a small amount of juice so the coffee remains smooth.", "Orange & coffee cream", "Infuse warm cream lightly with coffee and orange zest, strain and chill. Serve with a fresh orange segment."],
["orange", "carrot", 1, "Sweet root and sweet citrus make a rounded combination, while the orange’s acidity stops it feeling flat.", "Carrot & orange purée", "Cook carrots until tender, blend smooth and adjust with orange juice. Add a little fresh zest at the end."],
["orange", "chocolate", 1, "Bright citrus lifts cocoa’s roasted depth and bitterness. Zest gives a strong aromatic effect without adding much liquid.", "Dark chocolate & orange bark", "Spread melted dark chocolate thinly and finish with fine orange zest and a few flakes of salt."],
["lime", "coriander", 1, "Sharp citrus and fresh green leaves reinforce each other’s brightness. Add both near serving to preserve their aroma.", "Lime & coriander dressing", "Whisk lime juice with a mild oil and salt. Fold in finely chopped coriander leaves just before serving."],
["lime", "mango", 1, "Lime acid gives ripe mango a cleaner finish. A little zest adds aroma without making the fruit too sour.", "Mango with lime & salt", "Slice ripe mango and dress with a little lime juice, zest and a few grains of salt."],
["lime", "ginger", 1, "Two different kinds of citrus-like freshness meet, with ginger adding warmth. Balance the heat before adding more acid.", "Ginger & lime dressing", "Mix finely grated ginger with lime juice and a little sugar. Whisk in oil and taste before dressing vegetables."],
["lime", "scallop", 2, "A tiny citrus accent balances the scallop’s sweetness and richness. Add lime after cooking to retain a fresh finish.", "Seared scallop, lime zest", "Sear scallops until opaque and just cooked through. Finish with a little lime zest and a few drops of juice."],
["lime", "chilli", 1, "Acidity and heat create a vivid seasoning. Fresh chilli also brings fruit notes that are lost in a heavy cooked sauce.", "Fresh chilli & lime relish", "Finely chop a mild chilli and mix with lime juice, a pinch of sugar and salt. Use as a small finishing condiment."],
["grapefruit", "rosemary", 2, "Piney aroma and citrus bitterness make a structured, adult-tasting combination. Keep the rosemary infusion short.", "Grapefruit & rosemary granita", "Mix grapefruit juice with light rosemary-infused syrup. Freeze, scrape and serve in a small portion."],
["grapefruit", "fennel", 1, "Anise sweetness softens grapefruit’s bitter edge, while the citrus keeps raw fennel lively.", "Grapefruit & fennel salad", "Toss grapefruit segments with shaved fennel and olive oil. Add a pinch of salt and the reserved citrus juice."],
["grapefruit", "scallop", 2, "Bitter citrus can frame a sweet scallop without a heavy sauce. Use a small, clean segment and remove the membranes.", "Scallop with pink grapefruit", "Sear scallops until opaque and cooked through. Serve with a small grapefruit segment and a little olive oil."],
["grapefruit", "vanilla", 3, "Vanilla’s sweet aroma can soften the impression of bitter citrus without needing a large amount of sugar.", "Grapefruit with vanilla syrup", "Lightly infuse syrup with vanilla and cool. Dress grapefruit segments sparingly and taste before adding more."],
["grapefruit", "honey", 1, "Floral sweetness rounds the bitter citrus edge. Choose a mild honey so the grapefruit remains the main aroma.", "Grapefruit & honey dressing", "Whisk grapefruit juice with a little honey and olive oil. Taste for bitterness and acidity before dressing leaves."],
["pineapple", "chilli", 1, "Juicy acidity and sweetness give chilli heat a bright backdrop. Charring adds a bitter edge that keeps it interesting.", "Charred pineapple & red chilli", "Grill pineapple until marked, then add finely sliced chilli, lime and a pinch of salt."],
["pineapple", "basil", 2, "Green, floral basil adds a fresh layer to tropical fruit. The pairing works best when the basil stays raw.", "Pineapple & basil salad", "Dice fresh pineapple, add torn basil and a little lime juice. Serve immediately while the leaves are fragrant."],
["pineapple", "pork", 1, "Sweet acid balances rich pork; a grilled fruit garnish adds caramel without needing a sweet sauce.", "Pork with grilled pineapple salsa", "Cook pork through. Serve with grilled pineapple diced with red onion, lime and coriander."],
["pineapple", "miso", 3, "Fermented salt gives grilled tropical fruit a savoury turn. Use a very thin glaze to avoid overwhelming the fruit.", "Miso-glazed pineapple", "Grill pineapple wedges, then brush lightly with white miso loosened with water and a little lime juice."],
["pineapple", "vanilla", 1, "Vanilla rounds tropical acidity into a softer dessert profile. Roasting the fruit adds a useful caramelised edge.", "Roast pineapple & vanilla", "Roast pineapple wedges with a little vanilla-infused syrup. Serve warm with their reduced juices."],
["mango", "chilli", 1, "Chilli turns ripe fruit into a vivid sweet–hot contrast. A firm mango gives a crisper, less dessert-like result.", "Mango & chilli salad", "Cut firm mango into matchsticks and dress with lime, mild chilli and salt."],
["mango", "coriander", 1, "Fresh green leaves cut through mango’s rich perfume. Use the leaves generously enough to be aromatic but not pasty.", "Mango & coriander salsa", "Dice mango and fold through chopped coriander, lime juice and a little finely cut red onion."],
["mango", "ginger", 2, "Warm, citrus-like ginger adds definition to rich tropical fruit. Freshly grated ginger gives a brighter result than dried spice.", "Mango & ginger relish", "Finely dice mango and season with a little fresh ginger, lime and salt. Rest briefly before tasting again."],
["mango", "cardamom", 2, "Cool spice and tropical perfume create a layered combination. A short infusion is easier to balance than ground spice.", "Mango with cardamom cream", "Infuse cream with a bruised cardamom pod, strain and cool. Serve a small spoon beside ripe mango."],
["passionfruit", "chocolate", 1, "Sharp tropical acidity cuts cleanly through cocoa’s richness. Keep the fruit element unsweetened until you taste the full bite.", "Passionfruit & chocolate crémeux", "Serve a small chocolate crémeux with a spoon of fresh passionfruit pulp, adjusting sweetness only if necessary."],
["passionfruit", "scallop", 3, "An intense fruit accent can sharpen a sweet scallop. This is an exploratory pairing: use only a few drops of the juice.", "Scallop with passionfruit dressing", "Sear scallops until cooked through. Emulsify a little strained passionfruit juice with oil and salt, then use sparingly."],
["passionfruit", "vanilla", 1, "Sweet-smelling vanilla softens the impression of the fruit’s sharp acidity. The contrast works especially well in a cream base.", "Vanilla cream & passionfruit", "Set a lightly sweetened vanilla cream and top with fresh passionfruit pulp just before serving."],
["passionfruit", "carrot", 3, "Tropical acidity can brighten sweet, earthy carrot without requiring a heavy citrus dressing.", "Roast carrot, passionfruit glaze", "Roast carrots until tender. Toss with a little strained passionfruit juice and olive oil, tasting before adding more."],
["passionfruit", "honey", 2, "Floral honey softens the fruit’s acid edge. The fruit should still feel vivid rather than syrupy.", "Passionfruit & honey vinaigrette", "Whisk strained passionfruit juice with a small amount of honey and a neutral oil. Season and taste on a salad leaf."],
["fig", "blue-cheese", 1, "Honeyed fruit balances salt and pungency, while the cheese prevents the fig’s softness from feeling one-note.", "Warm fig & blue cheese", "Warm halved figs briefly, then add a small crumble of blue cheese and serve on crisp bread."],
["fig", "pepper", 2, "Woody spice gives jammy fruit a more savoury finish. Grind the pepper fresh and use it with restraint.", "Roast figs, cracked pepper", "Roast halved figs with a little olive oil. Finish with black pepper and a few drops of vinegar."],
["fig", "rosemary", 2, "Resinous herb adds a darker aromatic edge to the fig’s honeyed sweetness. A short infusion keeps the balance controlled.", "Fig & rosemary compote", "Warm chopped figs with a splash of water and a small rosemary sprig. Remove the sprig and balance with vinegar."],
["fig", "goat-cheese", 1, "Fresh cheese supplies tang and structure to soft, honeyed fruit. A crisp toast brings the textures together.", "Fig, chèvre & sourdough", "Spread chèvre onto warm toast, top with fresh fig slices and finish with a little olive oil."],
["fig", "coffee", 3, "A restrained roasted bitterness can make the fig’s sweetness feel deeper. Keep the coffee element light and separate.", "Fig with coffee cream", "Lightly infuse cream with coffee and chill. Serve a small spoon with roast fig halves and a pinch of salt."],
["watermelon", "cucumber", 1, "The two share a fresh, watery green impression. Contrast their textures with a fine cut and a light acidic dressing.", "Watermelon & cucumber salad", "Cube watermelon and thinly slice cucumber. Dress with lime and salt just before serving."],
["watermelon", "mint", 1, "Cool mint makes the fruit feel especially fresh. Tear the leaves at the last moment to avoid a bruised, muddy aroma.", "Watermelon & mint granita", "Blend watermelon with a little lime and freeze. Scrape into crystals and finish with torn mint."],
["watermelon", "tomato", 2, "Juicy sweetness and savoury acidity cross the fruit–vegetable boundary. Choose a ripe tomato with enough character to hold its own.", "Watermelon & tomato salad", "Mix watermelon cubes with ripe tomato wedges, olive oil and a little vinegar. Salt just before serving."],
["watermelon", "chilli", 2, "Sweet, watery fruit gives chilli a refreshing setting. Use mild fresh chilli and keep the pieces fine.", "Watermelon, chilli & lime", "Dress cold watermelon with lime, finely sliced chilli and flaky salt. Serve immediately."],
["watermelon", "goat-cheese", 2, "Salty tang and creaminess interrupt watermelon’s juicy sweetness. Add cheese in small, distinct pieces.", "Watermelon & chèvre salad", "Toss watermelon with leaves and a light vinaigrette. Add a few small pieces of fresh goat cheese at the end."],
["cucumber", "mint", 1, "Two different kinds of cool freshness reinforce each other. Keep both raw for the cleanest result.", "Cucumber & mint yoghurt", "Fold grated, lightly drained cucumber into yoghurt with chopped mint. Season with salt and lemon."],
["cucumber", "scallop", 2, "Crisp, green freshness provides a quiet contrast to a sweet scallop. Keep the cucumber dressing light and cold.", "Scallop with cucumber relish", "Finely dice cucumber with lemon and salt. Serve a small spoon beside a freshly seared, cooked scallop."],
["cucumber", "chilli", 1, "Cool crunch moderates the impression of heat. A little acid keeps the pairing sharp rather than watery.", "Smashed cucumber & chilli", "Lightly crush cucumber chunks, salt and drain briefly. Dress with chilli, vinegar and a little sesame oil."],
["cucumber", "apple", 2, "Crisp orchard fruit adds sweetness to a fresh green vegetable. Choose a tart apple and cut both to similar thickness.", "Cucumber & green apple salad", "Thinly slice cucumber and a tart apple. Dress lightly with lime and olive oil just before serving."],
["beetroot", "orange", 1, "Citrus acid and fresh zest cut through earthy sweetness. Roasting the beet first gives a more rounded base.", "Roast beetroot & orange", "Roast and peel beetroot, then dress warm wedges with orange segments, olive oil and a little vinegar."],
["beetroot", "goat-cheese", 1, "Tangy creaminess gives earthy beetroot a clear counterpoint. Keep some texture in the beet rather than blending everything smooth.", "Beetroot with whipped chèvre", "Whip fresh goat cheese until light. Serve with roast beet wedges and a sharp vinaigrette."],
["beetroot", "coffee", 3, "Earth and roast can make an unusually dark flavour combination. Dose the coffee as an accent and keep an acidic element nearby.", "Beetroot with coffee dressing", "Roast beetroot and dress with oil, vinegar and a few drops of cooled coffee. Taste each addition before serving."],
["beetroot", "hazelnut", 1, "Roasted nuts add warmth and crunch to a soft, sweet root. Acid stops the two rich flavours becoming heavy.", "Beetroot, hazelnut & vinegar", "Slice roasted beetroot and dress with sherry vinegar. Finish with chopped toasted hazelnuts and olive oil."],
["beetroot", "cumin", 2, "Warm, earthy spice echoes the beet’s depth. A little yoghurt or citrus can give the pairing a brighter finish.", "Beetroot & cumin yoghurt", "Roast beetroot, then serve over yoghurt seasoned with lightly toasted and ground cumin."],
["carrot", "cumin", 1, "Warm spice frames the root’s sweetness and gives it a savoury direction. Toast cumin lightly to avoid a bitter edge.", "Roast carrots with cumin", "Toss carrot wedges with oil, salt and lightly crushed toasted cumin. Roast until browned and tender."],
["carrot", "ginger", 1, "A warm, citrus-like accent keeps sweet carrot from feeling flat. Add some ginger late for a fresher aromatic finish.", "Carrot & ginger soup", "Cook carrots with a little ginger until tender, blend and season. Finish with a small amount of freshly grated ginger if needed."],
["carrot", "hazelnut", 2, "Roasted nut aroma reinforces browned carrot edges while adding texture. A touch of acid keeps the dish balanced.", "Carrots, hazelnut & lemon", "Roast carrots, then finish with chopped toasted hazelnuts, lemon juice and a little olive oil."],
["carrot", "vanilla", 3, "Vanilla’s sweet aroma can amplify carrot without adding sugar. Keep the infusion subtle to stay in savoury territory.", "Carrot purée with vanilla", "Cook carrots until soft. Briefly infuse a small piece of vanilla pod in the warm cooking liquid, remove and blend."],
["fennel", "pork", 1, "Anise aroma and mild savoury meat make a rounded combination. Roasting the fennel adds sweetness to balance the herbaceous notes.", "Pork with roast fennel", "Roast fennel wedges until tender. Serve with cooked pork and a little lemony pan juice."],
["fennel", "lemon", 1, "Citrus aroma and acidity sharpen fennel’s anise sweetness. Zest works when the dish already contains enough acid.", "Lemon-braised fennel", "Braise fennel wedges until tender. Finish with a little lemon juice, zest and the reserved fronds."],
["fennel", "scallop", 1, "Sweet, briny scallop sits comfortably alongside gentle anise. Cooked fennel is quieter than raw and easier to balance.", "Scallop & fennel purée", "Braise fennel and blend smooth. Serve a small spoon beneath a seared scallop cooked until opaque."],
["fennel", "vanilla", 3, "Two sweet-smelling aromas can make a delicate savoury combination. Keep the vanilla extremely restrained and season with salt.", "Fennel with vanilla beurre blanc", "Braise fennel until tender and dress with a light beurre blanc briefly infused with a tiny piece of vanilla pod."],
["celery", "blue-cheese", 1, "Crisp herbal bitterness cuts through pungent, fatty cheese. Keep the cheese in small pieces for a balanced bite.", "Celery & blue cheese salad", "Slice celery thinly and toss with leaves and vinaigrette. Scatter a small amount of blue cheese over the top."],
["celery", "hazelnut", 2, "Roasted nuts give celery’s green bitterness a warmer backdrop. A little lemon links the textures without covering the aroma.", "Celery & hazelnut crunch", "Thinly slice celery and combine with toasted chopped hazelnuts. Dress lightly with lemon and olive oil."],
["celery", "tomato", 1, "Herbal celery can add lift to savoury tomato. A small quantity is enough, especially when using the leaves.", "Tomato & celery broth", "Blend ripe tomatoes with a little celery, salt and vinegar. Strain well and serve cold with olive oil."],
["celery", "grapefruit", 2, "Bitter citrus and herbal crunch make a sharply defined salad. Add enough oil and a little sweetness to round the edges.", "Celery & grapefruit salad", "Toss fine celery slices with grapefruit segments, olive oil and a small drop of honey if needed."],
["asparagus", "butter", 1, "Rich butter rounds the spear’s vegetal character. A small squeeze of lemon keeps the combination light.", "Asparagus with cultured butter", "Steam or sauté asparagus until just tender. Finish with a small knob of cultured butter and a few drops of lemon."],
["asparagus", "parmesan", 1, "Nutty, salty cheese gives green asparagus savoury depth. Shave it finely so it melts slightly against the warm spear.", "Warm asparagus & Parmesan", "Cook asparagus briefly, dress with olive oil and cover with fine Parmesan shavings while warm."],
["asparagus", "miso", 2, "Fermented savouriness makes the green vegetable taste deeper. Thin the miso so it coats rather than smothers.", "Asparagus with white miso dressing", "Blanch asparagus until just tender. Dress with white miso whisked with water, lemon and a little oil."],
["asparagus", "coffee", 3, "A trace of roasted bitterness offers an unusual contrast to grassy asparagus. Start with only a few drops in the dressing.", "Grilled asparagus, coffee vinaigrette", "Grill asparagus and dress with oil, vinegar and a very small amount of cooled coffee. Taste before increasing the coffee."],
["cauliflower", "hazelnut", 1, "Roasting brings out nutty notes in the vegetable, while the actual nuts add crisp texture and a longer finish.", "Roast cauliflower & hazelnut", "Roast cauliflower florets until deeply golden. Finish with chopped toasted hazelnuts, lemon and parsley if available."],
["cauliflower", "coffee", 3, "Roasted cauliflower can carry a restrained bitter accent. Use coffee as a seasoning and include acid to keep it clear.", "Cauliflower with coffee butter", "Roast cauliflower wedges. Brush lightly with butter containing a few drops of reduced coffee and finish with lemon."],
["cauliflower", "miso", 2, "Fermented salt adds depth to a mild vegetable. Apply the glaze late so it does not burn before the cauliflower cooks.", "Miso-roasted cauliflower", "Roast cauliflower until nearly tender. Brush with diluted white miso, return briefly to the oven and finish with lemon."],
["cauliflower", "cumin", 1, "Warm, earthy spice gives roasted cauliflower a defined savoury character. Toasted seeds also add texture.", "Cauliflower with toasted cumin", "Roast cauliflower with oil and salt. Finish with lightly toasted crushed cumin and a spoon of yoghurt."],
["corn", "miso", 2, "Sweet kernels and fermented savouriness make a rounded combination. Reduce any added salt because the miso supplies its own.", "Sweetcorn with miso butter", "Grill or sauté corn, then toss with a small amount of butter mixed with white miso."],
["corn", "scallop", 1, "Sweet vegetable and sweet shellfish meet, while brininess keeps the dish savoury. A smooth corn base contrasts with a seared surface.", "Scallop with sweetcorn purée", "Cook corn kernels and blend to a smooth purée. Serve with a seared scallop cooked until opaque and finish with lime."],
["corn", "vanilla", 3, "A delicate vanilla infusion can draw attention to the corn’s sweetness. Keep it subtle and season the preparation as a savoury dish.", "Sweetcorn & vanilla velouté", "Cook corn in light stock. Briefly infuse a tiny piece of vanilla pod, remove it, blend and season with salt."],
["corn", "chilli", 1, "Juicy sweetness balances chilli heat. Charred corn also adds a bitter edge that makes the combination more complex.", "Charred corn & chilli", "Char cooked corn and cut off the kernels. Toss with finely sliced chilli, lime and a little oil."],
["pumpkin", "miso", 2, "Fermented salt counterbalances a sweet, starchy vegetable. A little acid makes the roasted edges feel less heavy.", "Roast pumpkin with miso glaze", "Roast pumpkin wedges until tender. Brush lightly with diluted miso and return to the oven; finish with lemon."],
["pumpkin", "hazelnut", 1, "Nutty crunch breaks up soft pumpkin, while roasting makes the flavours feel connected. Use a sharp dressing for balance.", "Pumpkin, hazelnut & sherry vinegar", "Roast pumpkin until golden and dress with sherry vinegar, olive oil and chopped toasted hazelnuts."],
["pumpkin", "blue-cheese", 2, "Pungent salt cuts through the root’s soft sweetness. Use the cheese as a small finishing garnish.", "Roast pumpkin with blue cheese", "Roast pumpkin wedges and crumble a small amount of blue cheese over them while warm. Add black pepper."],
["pumpkin", "ginger", 1, "Ginger’s warmth and citrus-like aroma give sweet pumpkin a brighter shape. Fresh ginger at the end adds extra lift.", "Pumpkin & ginger soup", "Cook pumpkin with a little onion and ginger, then blend smooth. Taste and finish with a small amount of fresh ginger if needed."],
["onion", "apple", 1, "Crisp orchard fruit and sharp onion balance sweetness and bite. Light pickling makes the combination easier to use as a garnish.", "Apple & red onion slaw", "Slice apple and red onion finely. Dress with cider vinegar, a little oil and salt; rest briefly."],
["onion", "thyme", 1, "Slow-cooked onion sweetness gives a warm herb a rounded backdrop. Add thyme late enough to keep some aroma.", "Roast onion & thyme", "Roast onion wedges until tender and caramelised. Add picked thyme leaves and a little vinegar before serving."],
["onion", "blue-cheese", 1, "Caramelised sweetness balances pungent salt. A crisp pastry or toast stops the combination feeling too soft.", "Onion & blue cheese tartine", "Slowly cook sliced onion until sweet. Spoon onto toast and add a little blue cheese just before serving."],
["onion", "raspberry", 3, "A tart berry dressing can turn lightly pickled onion into a bright, unusual garnish. Keep the onion cut very fine.", "Raspberry-pickled red onion", "Quick-pickle thin onion slices in vinegar with crushed raspberries and a little sugar. Drain before using as a garnish."],
["garlic", "mushroom", 1, "A restrained garlic accent deepens earthy mushrooms. Cook the garlic gently to avoid bitter burnt notes.", "Shiitake with soft garlic", "Sear shiitake until golden. Lower the heat, add finely chopped garlic and cook gently before seasoning."],
["garlic", "lemon", 1, "Fresh citrus lifts pungent garlic and keeps a rich preparation lively. Use zest for aroma and juice for acidity.", "Garlic & lemon dressing", "Crush a small garlic clove with salt. Whisk with lemon juice and olive oil, then taste before adding more garlic."],
["garlic", "honey", 2, "A small amount of floral sweetness rounds cooked garlic’s savoury edge. Keep enough acidity in the glaze for balance.", "Roast garlic & honey glaze", "Mash soft roasted garlic with a little honey, vinegar and water. Brush sparingly over roast vegetables."],
["garlic", "miso", 1, "Two assertive savoury ingredients can build depth quickly. Roast the garlic first for a softer, sweeter result.", "Roast garlic & miso butter", "Mash a roasted garlic clove into butter with a small amount of white miso. Use a little to finish cooked vegetables."],
["ginger", "pear", 2, "Warm spice gives a subtle pear more aromatic definition. A gentle infusion preserves the fruit’s delicate character.", "Ginger-poached pear", "Poach pear wedges with a few thin ginger slices in light syrup. Remove the ginger and serve with the poaching liquid."],
["ginger", "chocolate", 2, "Fresh ginger heat interrupts cocoa’s richness. An infusion gives a smoother result than large pieces of raw ginger.", "Ginger & dark chocolate ganache", "Infuse warm cream with sliced ginger, strain and use it to make a dark chocolate ganache."],
["ginger", "salmon", 1, "Citrus-like warmth and gentle pungency cut through salmon’s richness. Keep the glaze light so the fish stays central.", "Ginger-roasted salmon", "Brush salmon lightly with grated ginger, oil and a little soy sauce if desired. Roast until cooked through and finish with lime."],
["ginger", "scallop", 2, "A very small amount of fresh ginger gives delicate shellfish a bright aromatic edge. Avoid a heavy, hot sauce.", "Scallop with ginger dressing", "Sear scallops until cooked through. Serve with a few drops of ginger juice emulsified with oil and lime."],
["mint", "strawberry", 1, "Cool green aroma offers a clear contrast to sweet fruit. Tear mint gently and add it at the very last moment.", "Strawberries with fresh mint", "Slice ripe strawberries, add torn mint and a few drops of lemon. Taste before adding any sugar."],
["mint", "chocolate", 1, "Cooling freshness cuts through roasted richness. A short fresh-leaf infusion gives more control than concentrated mint flavouring.", "Fresh mint chocolate cream", "Infuse warm cream briefly with mint, strain and use it to make a light chocolate cream."],
["mint", "pineapple", 2, "Cooling herb brings a fresh finish to intense tropical fruit. A little lime helps separate the sweet and green notes.", "Pineapple & mint granita", "Blend pineapple with lime and a little syrup, freeze and scrape. Add finely torn mint to serve."],
["mint", "grapefruit", 2, "Cool mint gives bitter citrus a refreshing finish. Use only a few small leaves so the herb does not dominate.", "Grapefruit & mint salad", "Segment grapefruit, add a few torn mint leaves and dress with a little mild honey if needed."],
["rosemary", "chocolate", 3, "A piney infusion adds an unusual savoury edge to cocoa. The pairing needs restraint: taste the cream before making the ganache.", "Rosemary-infused chocolate ganache", "Infuse warm cream briefly with a small rosemary sprig. Remove, taste and use the cream to make dark chocolate ganache."],
["rosemary", "pork", 1, "Resinous herb and mild savoury meat make a robust combination. A whole sprig in the pan is easier to control than a heavy chopped coating.", "Pork with rosemary pan juices", "Cook pork through with a small rosemary sprig, then rest it. Deglaze the pan and serve the strained juices."],
["rosemary", "lemon", 1, "Pine and citrus make a bright, fragrant combination. Both are powerful, so use a little zest and a short herb infusion.", "Rosemary & lemon finishing oil", "Warm olive oil gently with rosemary and a strip of lemon zest. Remove both before using the oil on cooked vegetables."],
["rosemary", "hazelnut", 2, "Piney aroma gives warm, toasted nuts a savoury finish. Keep the rosemary finely chopped and use a small quantity.", "Warm rosemary hazelnuts", "Toast hazelnuts, then toss while warm with a little oil, finely chopped rosemary and salt."],
["thyme", "lemon", 1, "Warm herb and fresh citrus give a clear aromatic contrast. Add the citrus after cooking to keep it bright.", "Thyme & lemon butter", "Mix soft butter with picked thyme leaves and fine lemon zest. Use a small amount to finish vegetables or fish."],
["thyme", "mushroom", 1, "Warm herbal aroma sits comfortably against earthy mushrooms. Add the herb late enough to keep some freshness.", "Shiitake with thyme", "Sear shiitake until browned. Add picked thyme leaves near the end and finish with a little butter or oil."],
["thyme", "honey", 2, "Floral sweetness carries a warm herbal accent. A short infusion gives a more controlled result than a long steep.", "Thyme-infused honey", "Warm honey gently with a small thyme sprig, remove the sprig and cool. Use sparingly over roast fruit or cheese."],
["thyme", "peach", 2, "Soft stone fruit gains a gentle savoury edge from thyme. The herb is best used as an accent rather than a coating.", "Roast peach & thyme", "Roast peach halves with a small thyme sprig. Remove the sprig and serve with their juices and a little yoghurt."],
["coriander", "pineapple", 2, "Fresh green leaves give sweet, acidic pineapple a savoury direction. A little salt makes the contrast clearer.", "Pineapple & coriander salsa", "Finely dice pineapple with red onion. Add coriander leaves, lime juice and a pinch of salt."],
["coriander", "carrot", 1, "Citrus-green leaves brighten a sweet roasted root. Add them after cooking so their aroma remains distinct.", "Roast carrots & coriander", "Roast carrots until browned. Dress with lime and olive oil, then scatter with torn coriander leaves."],
["coriander", "salmon", 1, "Fresh leaves interrupt the fish’s richness without a heavy sauce. Combine them with acid for a cleaner finish.", "Salmon with coriander dressing", "Cook salmon through. Spoon over a dressing of chopped coriander, lime juice and a little oil."],
["coriander", "cumin", 1, "Cool green freshness and warm earthy spice give a useful layered seasoning. Toast the cumin and add the leaves fresh.", "Cumin & coriander dressing", "Mix lightly toasted ground cumin with lime and oil. Fold in chopped coriander leaves just before serving."],
["vanilla", "olive", 3, "Sweet-smelling vanilla and grassy oil make an unusual aromatic combination. Choose a mild oil and use very little vanilla.", "Vanilla-scented olive oil", "Warm a mild olive oil gently with a tiny piece of vanilla pod. Remove the pod and use a few drops on roast fruit."],
["vanilla", "scallop", 3, "A trace of vanilla can underline shellfish sweetness. Keep the sauce savoury and dose the infusion carefully.", "Scallop with vanilla butter", "Briefly infuse butter with a tiny piece of vanilla pod, remove it and season with salt. Spoon lightly over cooked scallops."],
["vanilla", "butter", 1, "Cultured butter carries vanilla aroma and adds a rounded finish. The pairing can season roast fruit without much extra sugar.", "Vanilla butter for roast fruit", "Mix soft butter with a small amount of scraped vanilla. Add to warm roast fruit and taste before sweetening."],
["vanilla", "lemon", 1, "Sweet aroma softens sharp citrus while zest keeps the combination lively. This is a useful balance for cream-based desserts.", "Lemon & vanilla cream", "Infuse cream with vanilla and lemon zest, strain and chill. Add a little lemon juice only if the recipe can accommodate it."],
["cardamom", "coffee", 1, "Cool, aromatic spice lifts roasted bitterness. Lightly bruise the pod rather than grinding a large quantity into the coffee.", "Cardamom coffee cream", "Infuse warm cream with coffee and a bruised cardamom pod, strain and use in a small dessert portion."],
["cardamom", "orange", 1, "Citrus and fragrant spice reinforce the impression of freshness. A little cardamom is enough to change a simple orange salad.", "Orange with cardamom syrup", "Infuse a light syrup with a bruised cardamom pod, cool and use sparingly to dress orange segments."],
["cardamom", "carrot", 2, "A cool spice accent gives sweet carrot an unexpected aromatic lift. Keep the cardamom light and season as a savoury dish.", "Carrot purée with cardamom", "Cook carrots with one bruised cardamom pod. Remove the pod, blend smooth and season with salt and lemon."],
["cardamom", "chocolate", 2, "Fragrant spice interrupts cocoa’s roasted richness. A short cream infusion gives a clean and controllable result.", "Cardamom chocolate truffle", "Infuse cream with a bruised cardamom pod, strain and use to make dark chocolate ganache. Chill and shape into small truffles."],
["cumin", "mango", 3, "Earthy spice gives tropical fruit a savoury edge. Start with a light dusting and let acidity keep the combination fresh.", "Green mango & toasted cumin", "Cut firm mango thinly and dress with lime, salt and a tiny pinch of toasted ground cumin."],
["cumin", "chocolate", 3, "Earthy warmth can pull cocoa into a savoury direction. Use unsweetened cocoa and a restrained amount of spice.", "Cocoa & cumin roast pumpkin", "Roast pumpkin with oil and salt. Finish with a tiny pinch each of toasted cumin and unsweetened cocoa, tasting carefully."],
["cumin", "tomato", 1, "Warm spice gives sweet, acidic tomato more depth. Toast cumin lightly before adding the tomato.", "Tomato & cumin sauce", "Toast cumin gently in oil, add chopped tomatoes and cook down. Balance with salt and a little vinegar if needed."],
["cumin", "pork", 1, "Warm, earthy spice seasons mild savoury meat. Keep the spice coating light so it does not burn in the pan.", "Cumin-spiced pork", "Season pork lightly with toasted ground cumin and salt. Cook through, rest and finish with lime."],
["chilli", "chocolate", 1, "Heat adds a different sensation to roasted cocoa. Add chilli gradually so the finish stays warm rather than harsh.", "Dark chocolate with chilli", "Stir a very small amount of finely ground chilli into melted dark chocolate. Spread thinly, cool and taste before increasing the dose."],
["chilli", "honey", 1, "Floral sweetness cushions chilli heat, while the heat keeps a sweet glaze from feeling flat. Add acid for balance.", "Fresh chilli honey glaze", "Warm honey gently with finely sliced chilli. Add a little vinegar and use sparingly as a glaze."],
["chilli", "scallop", 2, "A delicate shellfish can carry a small amount of fruity heat. Use a mild chilli and keep it away from a heavy sauce.", "Scallop with red chilli oil", "Warm oil briefly with finely sliced mild chilli. Drizzle a few drops over scallops seared until opaque and cooked through."],
["chilli", "peach", 2, "Juicy stone fruit gives chilli a soft, sweet backdrop. Grilling adds a slight bitter edge to the contrast.", "Grilled peach & chilli", "Grill peach wedges briefly and finish with finely sliced chilli, lime and a little salt."],
["coffee", "chocolate", 1, "Two roasted ingredients can reinforce each other. Coffee is most useful in a small amount that deepens cocoa without taking over.", "Coffee & dark chocolate crémeux", "Add a small amount of brewed coffee to the liquid in a chocolate crémeux recipe, then taste for balance."],
["coffee", "hazelnut", 1, "Roasted nut aroma links naturally with coffee’s toasted character. Keep one component mild so the pairing retains definition.", "Coffee cream & hazelnut", "Serve lightly infused coffee cream with chopped toasted hazelnuts and a small pinch of salt."],
["coffee", "pork", 3, "A light bitter-roasted seasoning gives pork an unexpected darker edge. Use fine coffee sparingly to avoid a gritty crust.", "Coffee-spiced pork", "Season pork with salt and a very small pinch of finely ground coffee. Cook through without scorching the coating, rest and serve with apple."],
["coffee", "vanilla", 1, "Vanilla’s sweet aroma rounds the impression of roasted bitterness. The combination needs less sugar when the coffee is gently extracted.", "Coffee & vanilla custard", "Lightly infuse milk or cream with coffee and vanilla, strain and use to make a custard."],
["hazelnut", "chocolate", 1, "Roasted nut aroma and cocoa bitterness make a familiar, rounded combination. A little salt keeps it from becoming overly sweet.", "Dark chocolate hazelnut clusters", "Coat toasted hazelnuts lightly in dark chocolate, add a few flakes of salt and leave to set."],
["hazelnut", "scallop", 2, "Roasted nuts bring crunch and warmth to sweet, delicate shellfish. Use chopped nuts rather than a heavy nut sauce.", "Scallop with hazelnut crumb", "Sear scallops until cooked through. Finish with a small spoon of chopped toasted hazelnuts, lemon zest and a little butter."],
["hazelnut", "mushroom", 2, "Earthy mushroom and roasted nut flavours give a deep, savoury combination. Lemon helps keep the rich elements distinct.", "Shiitake & hazelnut toast", "Sear shiitake and pile onto toast. Finish with chopped hazelnuts, lemon and a little olive oil."],
["hazelnut", "apricot", 1, "Soft, acidic stone fruit contrasts with toasted crunch. The pairing works well with lightly sweetened dairy or a savoury salad.", "Roast apricot & hazelnut", "Roast apricot halves until just soft. Scatter with toasted chopped hazelnuts and serve with thick yoghurt."],
["sesame", "strawberry", 3, "Roasted seed aroma gives bright fruit a savoury contrast. Start with a few toasted seeds or a very small amount of tahini.", "Strawberry with sesame cream", "Loosen tahini with water and a little lemon. Serve a small spoon with fresh strawberries and toasted sesame seeds."],
["sesame", "miso", 1, "Roasted seeds and fermented savouriness make a deep dressing. Thin it well so it coats lightly rather than becoming pasty.", "Sesame & miso dressing", "Whisk tahini with a little white miso, water and rice vinegar. Adjust the texture before dressing vegetables."],
["sesame", "salmon", 1, "Roasted seeds add texture and savoury warmth to rich fish. Keep a fresh acidic element nearby.", "Sesame-roasted salmon", "Coat salmon lightly with sesame seeds and cook through. Finish with lime and fresh herbs."],
["sesame", "chocolate", 2, "Toasted seed aroma gives cocoa an earthy, nutty dimension. A little salt helps define both flavours.", "Dark chocolate & sesame bark", "Spread melted dark chocolate thinly and scatter generously with toasted sesame seeds and a few flakes of salt."],
["sesame", "pear", 3, "A gentle roasted accent can bring depth to mild pear. Use tahini in a thin dressing rather than a thick paste.", "Pear with sesame dressing", "Slice a firm pear and dress lightly with tahini loosened with water, lemon and a small amount of honey."],
["honey", "goat-cheese", 1, "Floral sweetness rounds fresh cheese’s tang. A small drizzle is enough; leave the cheese as the main savoury element.", "Chèvre with warm honey", "Serve fresh goat cheese on toast and finish with a small drizzle of gently warmed honey and black pepper."],
["honey", "blue-cheese", 1, "Sweetness counterbalances pungent salt. Strong cheese benefits from a mild floral honey rather than a dominant one.", "Blue cheese & honey tasting bite", "Place a small piece of blue cheese on a crispbread and finish with just a drop of honey."],
["honey", "miso", 2, "Sweetness and fermented salt can create a balanced glaze. Thin the mixture and apply late to avoid burning.", "Honey & miso glaze", "Whisk white miso with a little honey, water and vinegar. Brush lightly onto nearly cooked vegetables and finish briefly in the oven."],
["honey", "lemon", 1, "Acidity keeps floral sweetness from feeling heavy. Zest adds aroma without requiring more juice.", "Honey & lemon dressing", "Whisk lemon juice with a little honey and olive oil. Season and taste on the ingredient you plan to dress."],
["miso", "butter", 1, "Butter rounds fermented salt and carries its savoury aroma. Use the mixture as a finishing seasoning, not a large sauce.", "White miso butter", "Mix softened butter with a small amount of white miso. Melt a little over hot vegetables, adjusting other salt accordingly."],
["miso", "chocolate", 3, "A small fermented-salty accent gives cocoa a savoury edge. The amount should be low enough that the chocolate remains dominant.", "White miso chocolate ganache", "Whisk a little white miso into warm cream, then use it for a dark chocolate ganache. Taste before adding any salt."],
["miso", "salmon", 1, "Fermented sweetness and salt work well against rich fish. A thin glaze gives flavour without hiding the salmon.", "Miso-roasted salmon", "Loosen white miso with water and a little rice vinegar. Brush lightly onto salmon and roast until cooked through."],
["miso", "goat-cheese", 3, "Two tangy, savoury ingredients make an intense spread. Use miso in a very small quantity and add fresh fruit for contrast.", "Chèvre with a touch of miso", "Whip fresh goat cheese with a tiny amount of white miso. Serve sparingly on toast with crisp apple."],
["butter", "lemon", 1, "Citrus gives rich butter a cleaner finish. Zest supplies aroma; juice should be added carefully to the intended sauce.", "Lemon finishing butter", "Mix softened butter with fine lemon zest and a little salt. Melt a small amount over warm vegetables or cooked fish."],
["butter", "scallop", 1, "A small amount of butter rounds sweet shellfish and carries the seared aroma. Keep the pan hot enough to colour without burning the butter.", "Butter-finished scallop", "Sear scallops in a little oil until cooked through. Add a small knob of butter at the end and spoon over briefly."],
["butter", "coffee", 3, "A trace of roasted bitterness changes a rich butter sauce. Dose coffee carefully and keep the sauce savoury.", "Coffee butter for roast vegetables", "Mix a few drops of reduced coffee into warm butter. Taste, add salt and use a small amount on roasted cauliflower."],
["butter", "rosemary", 1, "Butter carries the herb’s resinous aroma and makes it easy to dose. Infuse a whole sprig and remove it.", "Rosemary butter", "Warm butter gently with a small rosemary sprig. Remove the sprig and use a little to finish roast vegetables or meat."],
["blue-cheese", "chocolate", 3, "Pungent salt and roasted bitterness make an intense exploratory bite. Use tiny portions and adjust the ratio at the table.", "Blue cheese & dark chocolate shard", "Serve a very small piece of blue cheese beside a thin shard of dark chocolate. Taste different proportions before developing a dish."],
["blue-cheese", "pineapple", 3, "Tropical acidity and sweetness can interrupt a strong, salty cheese. Grilled fruit makes the contrast easier to balance.", "Grilled pineapple with blue cheese", "Grill pineapple wedges, then add a very small crumble of blue cheese while warm. Finish with black pepper."],
["blue-cheese", "beetroot", 2, "Earthy sweetness provides a base for pungent cheese, while vinegar keeps the combination lively.", "Beetroot with blue cheese dressing", "Roast beetroot and dress with vinegar. Add a light dressing made from a small amount of blue cheese loosened with yoghurt."],
["blue-cheese", "hazelnut", 1, "Roasted crunch gives creamy, pungent cheese texture and a warmer finish. Serve with a fresh acidic element.", "Blue cheese & hazelnut salad", "Toss leaves with a sharp vinaigrette and scatter with a little blue cheese and chopped toasted hazelnuts."],
["goat-cheese", "lemon", 1, "Fresh citrus lifts tangy dairy and keeps a whipped cheese preparation light. Use mostly zest when the cheese is already sharp.", "Whipped chèvre with lemon", "Whip fresh goat cheese with a little yoghurt and fine lemon zest. Adjust with juice only after tasting."],
["goat-cheese", "thyme", 1, "A small amount of warm herb makes fresh cheese more savoury. Pick young leaves and keep the texture fine.", "Thyme & chèvre toast", "Spread fresh goat cheese onto toast and finish with picked thyme leaves, olive oil and black pepper."],
["goat-cheese", "coffee", 3, "A tiny roasted-bitter accent gives tangy cheese an unexpected finish. Start with a few drops rather than a dusting of dry grounds.", "Chèvre with coffee syrup", "Whip fresh goat cheese until light. Serve a small tasting portion with a few drops of lightly sweetened reduced coffee."],
["goat-cheese", "cucumber", 1, "Cool crunch contrasts with soft tangy cheese. A fresh herb and a little acid keep the pairing clean.", "Cucumber & chèvre salad", "Slice cucumber and dress lightly with lemon. Add small pieces of fresh goat cheese and mint just before serving."],
["scallop", "cauliflower", 1, "A mild vegetable purée supports sweet shellfish without masking it. Roasting part of the cauliflower adds a nutty contrast.", "Scallop & cauliflower purée", "Cook cauliflower until soft and blend smooth. Top with a scallop seared until opaque and cooked through."],
["scallop", "apple", 2, "A crisp, acidic garnish cuts through the scallop’s sweetness and rich seared surface. Keep the apple finely cut.", "Scallop with green apple relish", "Dice tart apple finely with lemon and a little oil. Spoon beside a freshly cooked scallop."],
["scallop", "chocolate", 3, "A trace of cocoa offers a deliberately exploratory roasted contrast. Keep it unsweetened and very light so the shellfish stays central.", "Scallop with a cocoa accent", "Sear a scallop until cooked through and serve with cauliflower purée. Add the smallest pinch of unsweetened cocoa to the plate and taste cautiously."],
["scallop", "lemon", 1, "Fresh acidity and citrus aroma give delicate shellfish a clean finish. Add lemon after cooking so the aroma remains bright.", "Seared scallop with lemon", "Sear scallops until opaque and just cooked through. Finish with a few drops of lemon juice and a little zest."],
["salmon", "beetroot", 1, "Earthy sweetness and bright acidity balance rich salmon. Roast the beetroot and keep the dressing sharp.", "Salmon with roast beetroot", "Cook salmon through and serve with roast beet wedges dressed in lemon and olive oil."],
["salmon", "fennel", 1, "Anise freshness lightens rich fish. Raw shaved fennel gives more contrast; braised fennel gives a softer result.", "Salmon & shaved fennel", "Roast salmon until cooked through. Serve with finely shaved fennel dressed with lemon and olive oil."],
["salmon", "grapefruit", 2, "Bitter citrus cuts through rich fish and adds a fresh finish. Use a clean segment without membrane to avoid excessive bitterness.", "Salmon with grapefruit dressing", "Cook salmon through. Dress with a small amount of grapefruit juice and olive oil, then add a few segments."],
["salmon", "raspberry", 3, "Tart red fruit can give a rich fish a striking acidic counterpoint. Keep the dressing savoury and use it sparingly.", "Salmon with raspberry vinaigrette", "Roast salmon until cooked through. Spoon over a little crushed raspberry, vinegar and oil dressing with no added sugar."],
["duck", "fig", 1, "Honeyed fruit sits against rich savoury meat, while vinegar keeps the balance from becoming too sweet.", "Duck with roast fig", "Cook duck breast and rest it. Warm fig halves in the pan, add a little vinegar and serve with the strained juices."],
["duck", "coffee", 3, "Roasted bitterness can add depth to rich meat. Use coffee as a small part of the sauce, not a thick coating.", "Duck with a coffee jus", "Cook and rest duck. Reduce the pan juices with stock, then add a little brewed coffee and taste before increasing it."],
["duck", "rosemary", 1, "A restrained piney aroma gives rich meat a savoury frame. Use a small whole sprig so it can be removed easily.", "Rosemary-scented duck", "Cook duck with a small rosemary sprig during the final stage. Remove the herb, rest the meat and serve with the pan juices."],
["duck", "miso", 2, "Fermented salt gives duck a deeper savoury finish. Apply a thin glaze at the end because it colours quickly.", "Duck with a light miso glaze", "Cook duck breast, then brush lightly with diluted white miso near the end. Rest before slicing and serve with something acidic."],
["pork", "blackberry", 2, "Dark fruit acidity cuts through rich meat, and a savoury base keeps the sauce from tasting like jam.", "Pork with blackberry sauce", "Cook pork through and rest. Deglaze with stock, add crushed blackberries and balance with a little vinegar."],
["pork", "sesame", 2, "Roasted seed aroma and crisp texture give mild pork more depth. Finish with citrus to keep the richness in check.", "Sesame-crusted pork", "Coat pork lightly with sesame seeds and cook through without scorching. Rest and serve with lime and cucumber."],
["pork", "vanilla", 3, "A very subtle sweet-smelling infusion can round a savoury pork sauce. Keep it restrained and add acidity.", "Pork with a vanilla pan sauce", "Cook pork through and rest. Deglaze with stock, briefly infuse a tiny piece of vanilla pod, remove and finish with cider vinegar."],
];
export const pairings: Pairing[] = rows.map(([a,b,novelty,why,dish,method]) => {
  const ai=ingredients.find(i=>i.id===a)!; const bi=ingredients.find(i=>i.id===b)!;
  const shared=ai.compounds.filter(c=>bi.compounds.some(d=>d.name===c.name));
  return {id:[a,b].sort().join(':'),a,b,novelty,type:shared.length?'bridge':'contrast',connection:shared.length?shared[0].name:`${ai.notes[0]} × ${bi.notes[0].toLowerCase()}`,why,dish,method};
});
export const getIngredient=(id:string)=>ingredients.find(i=>i.id===id)!;
export const otherIngredient=(p:Pairing,id:string)=>getIngredient(p.a===id?p.b:p.a);
export const noveltyLabel=(n:number)=>n===1?'Familiar':n===2?'Unexpected':'Exploratory';
export const isPlantIngredient=(i:Ingredient)=>!['Dairy','Meat','Seafood'].includes(i.category)&&i.id!=='honey';
export function findPairings(seed:string,type:string,novelty:number,plantOnly=false) {
 return pairings.filter(p=>(p.a===seed||p.b===seed)&&(type==='all'||p.type===type)&&(!plantOnly || (isPlantIngredient(getIngredient(p.a))&&isPlantIngredient(getIngredient(p.b))))).sort((a,b)=>Math.abs(a.novelty-novelty)-Math.abs(b.novelty-novelty)||a.id.localeCompare(b.id));
}
